INSERT INTO `taxonomy` VALUES (1,NULL,36,'Dominant','D','Trees with well developed crowns extending above the general level of the forest canopy. The crown receives full sunlight from above and partly from the sides.'),(2,NULL,36,'Co-dominant','C','Trees with medium-sized crowns forming the general level of the forest canopy. Each tree crown receives full sunlight from above but very little from the sides.'),(3,NULL,36,'Intermediate','I','Trees shorter than dominant and co-dominant trees and have small crowns extending into the forest canopy. Each tree receives a little direct light from holes in the canopy and very little light from the sides.'),(4,NULL,36,'Suppressed','S','Trees with crowns more or less entirely below the forest canopy and receiving very little direct light either from above or from the sides.'),(5,NULL,36,'Emergent','E','Trees with crowns totally above the canopy of the stand and receiving full sunlight from both above and from all sides.'),(6,NULL,36,'Open grown','OG','Trees not growing near any other tree and with crowns receiving full sunlight from both above and from all sides.'),(7,NULL,67,'ASD Integrating Sphere (2003 or newer)','','Analytical Spectral Devices integrating sphere, as produced after 2003'),(8,NULL,67,'ASD Integrating Sphere (before 2003)','','Analytical Spectral Devices integrating sphere, as produced before 2003'),(9,NULL,67,'LI-COR 1800-12','',''),(10,NULL,158,'LAGOS','LAGOS','RLSs Laboratory Goniometer System'),(11,NULL,158,'FIGOS','FIGOS','RLSs Field Goniometer System'),(12,NULL,158,'FIGIFIGO','FIGIFIGO','FGIs Field Goniometer System'),(13,NULL,159,'Sun','','Natural irradiance provided by the sun'),(14,NULL,159,'Oriel 1000 W QTH','',''),(15,NULL,160,'Bidirectional (CASE 1)','1',''),(16,NULL,160,'Directional-conical (CASE 2)','2',''),(17,NULL,160,'Directional-hemispherical (CASE 3)','3',''),(18,NULL,160,'Conical-directional (CASE 4)','4',''),(19,NULL,160,'Biconical (CASE 5)','5',''),(20,NULL,160,'Conical-hemispherical (CAS